#include "multi_face_fixtures.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <iostream>
using namespace MultiFaceFixtures;
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{QTemporaryDir tmp;const auto folder=argc>1 ? QString::fromLocal8Bit(argv[1]) : tmp.path();const auto meta=create(folder);
    for(const auto& fixture:std::initializer_list<std::pair<QString,QJsonObject>>{{"plate40",meta["plate"].toObject()},{"inclined",meta["inclined"].toObject()}}){CadDocument d;check(d.open(folder+"/"+fixture.first+".alloy").isEmpty(),"fixture open");const auto target=fixture.second["targetBodyId"].toString();EvaluatedSupportFace support;for(const auto& face:d.bodies()[0].supportFaces){const auto n=face.frame["normal"].toArray();if(fixture.first=="plate40" ? n[1].toDouble()<-.99 : std::abs(n[0].toDouble())>.1 && std::abs(n[2].toDouble())>.1)support=face;}check(!support.faceId.isEmpty(),"new support exists");const auto width=fixture.first=="plate40" ? 8:6;auto sketch=SketchGeometry::newSupportedFeature(d.authored()["documentId"].toString(),ref(support),"New face boss");sketch=SketchGeometry::addRectangle(sketch,{{"u1Mm",10},{"v1Mm",1},{"u2Mm",10+width},{"v2Mm",4}});commit(d,SketchGeometry::replaceFeature(d.authored(),sketch));const auto before=d.authored();const double volume=d.bodies()[0].summary["volumeMm3"].toDouble();const double distance=fixture.first=="plate40" ? 4:2;auto candidate=CadDocument::extrusionCandidate(d.authored(),{{"sketchId",sketch["id"]},{"profileId",d.sketches().back().profiles[0].profileId},{"distanceMm",distance},{"operation","join"},{"targetBodyIds",QJsonArray{target}}});const auto preview=CadDocument::evaluateCandidate(candidate);check(preview.ok && d.authored()==before,"real disposable Join preview");commit(d,candidate);check(d.bodies().size()==1 && d.bodies()[0].bodyId==target,"Join retains target");check(std::abs(d.bodies()[0].summary["volumeMm3"].toDouble()-volume-width*3*distance)<1e-5,"normal-directed boss volume");check(d.sketches().back().resolvedFrame==support.frame,"support frame stable through Join");const auto after=d.authored();d.history().undo();check(d.authored()==before,"boss undo");d.history().redo();check(d.authored()==after,"boss redo");check(d.save(folder+"/"+fixture.first+"-joined.alloy").isEmpty(),"joined save");}
    CadDocument d;check(d.open(folder+"/support-failure.alloy").isEmpty(),"failure open");const auto f=meta["failure"].toObject();const auto before=d.authored();const auto revision=d.revision();const auto count=d.history().count();for(auto key:{"splitBodyId","deleteBodyId"}){auto candidate=CadDocument::booleanCandidate(d.authored(),{{"featureId",f["combineFeatureId"]},{"targetBodyId",f["targetBodyId"]},{"toolBodyIds",QJsonArray{f[key]}},{"operation","cut"},{"keepTools",true}});check(!d.commit(candidate,"Break support").isEmpty(),"unsupported topology refused");const auto error=d.lastEvaluationError();check(error["code"]=="support_unavailable" && error["featureId"]==f["sketchId"] && error["featureType"]=="sketch" && error["faceId"]==f["support"].toObject()["faceId"] && error["producerFeatureId"]==f["support"].toObject()["producerFeatureId"] && error["bodyId"]==f["targetBodyId"],"failure reports exact sketch/support");check(d.authored()==before && d.revision()==revision && d.history().count()==count,"failed edit atomic");}std::cout<<"PASS: cumulative side/inclined Join, frames, atomic split/deleted support and fixtures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
